1	import type { Booking } from "@harbor/dispatch/types";
2	
3	function overlaps(a: Booking, b: Booking): boolean {
4	  return a.start.getTime() <= b.end.getTime() && b.start.getTime() <= a.end.getTime();
5	}
6	
7	export class BerthSchedule {
8	  #bookings: Booking[] = [];
9	
10	  book(booking: Booking): void {
11	    if (booking.end.getTime() <= booking.start.getTime()) {
12	      throw new RangeError("a booking must end after it starts");
13	    }
14	    const clash = this.#bookings.find((b) => b.berth === booking.berth && overlaps(b, booking));
15	    if (clash) {
16	      throw new Error(`berth ${booking.berth} is already booked for ${clash.vessel}`);
17	    }
18	    this.#bookings.push(booking);
19	  }
20	
21	  bookingsFor(berth: string): Booking[] {
22	    return this.#bookings
23	      .filter((b) => b.berth === berth)
24	      .sort((a, b) => a.start.getTime() - b.start.getTime());
25	  }
26	}
