1	import assert from "node:assert/strict";
2	import { describe, test } from "node:test";
3	import { berthsFor, fitsBerth } from "@harbor/dispatch/berths/fit";
4	import { BerthSchedule } from "@harbor/dispatch/berths/schedule";
5	import type { Berth, VesselClass } from "@harbor/dispatch/types";
6	
7	const vessel: VesselClass = { name: "Test", lengthM: 300, beamM: 40, draftM: 12, teu: 8000 };
8	const berth = (id: string, lengthM: number, depthM: number): Berth => ({ id, port: "NLRTM", lengthM, depthM });
9	const at = (hhmm: string) => new Date(`2026-05-04T${hhmm}:00Z`);
10	
11	describe("berth fit", () => {
12	  test("a vessel longer than the berth does not fit", () => {
13	    assert.equal(fitsBerth(vessel, berth("B1", 280, 16)), false);
14	  });
15	
16	  test("a deep, long berth fits", () => {
17	    assert.equal(fitsBerth(vessel, berth("B2", 350, 16)), true);
18	  });
19	
20	  test("candidate berths, shortest first", () => {
21	    const got = berthsFor(vessel, [berth("B3", 400, 17), berth("B1", 280, 16), berth("B2", 350, 16)]);
22	    assert.deepEqual(got.map((b) => b.id), ["B2", "B3"]);
23	  });
24	});
25	
26	describe("berth schedule", () => {
27	  test("overlapping bookings on one berth are refused", () => {
28	    const s = new BerthSchedule();
29	    s.book({ berth: "B1", vessel: "MSC Ada", start: at("08:00"), end: at("12:00") });
30	    assert.throws(() => s.book({ berth: "B1", vessel: "Maersk Iva", start: at("10:00"), end: at("14:00") }));
31	  });
32	
33	  test("other berths are independent", () => {
34	    const s = new BerthSchedule();
35	    s.book({ berth: "B1", vessel: "MSC Ada", start: at("08:00"), end: at("12:00") });
36	    s.book({ berth: "B2", vessel: "Maersk Iva", start: at("10:00"), end: at("14:00") });
37	    assert.equal(s.bookingsFor("B2").length, 1);
38	  });
39	
40	  test("a booking must end after it starts", () => {
41	    const s = new BerthSchedule();
42	    assert.throws(() => s.book({ berth: "B1", vessel: "MSC Ada", start: at("12:00"), end: at("08:00") }), RangeError);
43	  });
44	});
